public class ClipWindowPainterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String pixel(java.awt.image.BufferedImage img, int x, int y) {
        if (img == null) {
            return "null-image";
        }
        return String.format("#%06X", img.getRGB(x, y) & 0xFFFFFF);
    }

    static java.awt.image.BufferedImage render(int width, int height,
                                               int cx, int cy, int cw, int ch) {
        java.awt.image.BufferedImage img = new java.awt.image.BufferedImage(
                width, height, java.awt.image.BufferedImage.TYPE_INT_RGB);
        java.awt.Graphics2D g = img.createGraphics();
        try {
            ClipWindowPainter.paint(g, width, height, cx, cy, cw, ch);
        } finally {
            g.dispose();
        }
        return img;
    }

    public static void main(String[] args) {
        try {
            java.awt.image.BufferedImage a = render(60, 60, 20, 20, 20, 20);
            java.awt.image.BufferedImage b = render(40, 40, 0, 0, 40, 10);
            check("inside the clip window (30,30)", "#0000FF", pixel(a, 30, 30));
            check("just inside the clip corner (25,25)", "#0000FF", pixel(a, 25, 25));
            check("left of the clip window (12,30)", "#FFFFFF", pixel(a, 12, 30));
            check("above the clip window (30,12)", "#FFFFFF", pixel(a, 30, 12));
            check("below-right of the clip window (48,48)", "#FFFFFF", pixel(a, 48, 48));
            check("red marker survives setClip(null) (4,4)", "#FF0000", pixel(a, 4, 4));
            check("clipped top strip is blue (20,5)", "#0000FF", pixel(b, 20, 5));
            check("area under the strip stays white (20,25)", "#FFFFFF", pixel(b, 20, 25));
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

